import BaseService from "./BaseService";
import http from "./HttpService";
import { API_BASE_URL_ENV } from "../jsx/common/common";

const apiEndpoint = API_BASE_URL_ENV() + "/admin/customs-clearance/requests";
const apiAssignEndpoint =
	API_BASE_URL_ENV() + "/admin/customs-clearance/requests/broker";

export default class ClearanceService extends BaseService {
	constructor() {
		super(apiEndpoint);
	}

	assignBroker(id, data) {
		const body = { ...data };
		return http.patch(`${apiAssignEndpoint}/${id}`, body);
	}
}
