import React, { useEffect, useState } from "react";
import { Card, Col, Row } from "react-bootstrap";
import { useSelector } from "react-redux";
import AdminService from "../../../services/AdminService";
import "./style.scss";
import { Translate } from "../../Enums/Tranlate";
import { useNavigate } from "react-router-dom";

const Home = () => {
	const [formData, setFormData] = useState({
		totalUsers: "",
		totalAdmins: "",
		totalBrokers: "",
		totalClearance: "",
		totalTranSport: "",
		totalRoles: "",
	});
	const [loading, setLoading] = useState(false);
	const navigate = useNavigate();
	const adminService = new AdminService();
	const lang = useSelector((state) => state.auth.lang);

	useEffect(() => {
		setLoading(true);
		adminService.getDashboard().then((res) => {
			if (res && res?.status === 200) {
				setFormData(res.data.data);
			}
			setLoading(false);
		});
	}, []);

	if (loading) {
		return (
			<Row>
				{Object.entries(formData)?.map(() => {
					return (
						<Col className="col-md-3 col-sm-6">
							<Card style={{ height: "172px" }}>
								<Card.Body>
									<div className="skeleton-loader">
										<div
											style={{ height: "32px", width: "32px" }}
											className="loader-header"></div>
										<div className="loader-content"></div>
										<div
											style={{ height: "40px" }}
											className="loader-content mb-0"></div>
									</div>
								</Card.Body>
							</Card>
						</Col>
					);
				})}
			</Row>
		);
	}

	return (
		<div className="row dashboard">
			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/admins")}>
					<div className="card-body">
						<i
							class="fa fa-shield text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].total_admins}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.admins?.total}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>
			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/roles")}>
					<div className="card-body">
						<i
							class="fa fa-shield text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].roles}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.admins?.totalRoles}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>
			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/broker-managment")}>
					<div className="card-body">
						<i
							class="fa fa-users text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].total_brokers}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.brokers?.total}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>
			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/users")}>
					<div className="card-body">
						<i
							class="fa fa-users text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].total_users}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.users?.total}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>

			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/clearance")}>
					<div className="card-body">
						<i
							class="fa fa-ship text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].total_clearance}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.customsClearance?.total}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>
			<div className="col-md-3 col-sm-6">
				<div className="card" onClick={() => navigate("/transport")}>
					<div className="card-body">
						<i
							class="fa fa-truck text-primary mb-2"
							style={{ fontSize: "32px" }}
						/>
						<p className="mb-1">{Translate[lang].total_tranSport}</p>
						<p className="fs-32 mb-0 text-black font-w700">
							{formData?.transport?.total}
						</p>
					</div>
					<div class="wave-container">
						<div class="wave"></div>
						<div class="wave"></div>
						<div class="wave"></div>
					</div>
				</div>
			</div>

			{/* <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <i className='la la-truck' style={{fontSize: '2rem'}}></i>
                <div>
                  <span className="fs-32 text-black font-w600">
                    {formData.totalOrders}
                  </span>
                  <p className="fs-14 mb-1">{Translate[lang]?.total_orders}</p>
                </div>
              </div>
            </div>
          </div> */}
			{/* <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-center">
                  <div style={{ textAlign: lang=== 'ar' ? 'right' : 'left'}}>
                    <p className="fs-14 mb-1">{Translate[lang]?.orders} (<span className="text-primary">{Translate[lang]?.on_the_way}</span>)</p>
                    <span className="fs-32 text-black font-w600">
                    {formData.ordersOnTheWay}
                    </span>
                  </div>
                  <i className='la la-truck text-primary' style={{fontSize: '2rem'}}></i>
                </div>
              </div>
            </div>
          </div>
          <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-center">
                  <div style={{ textAlign: lang=== 'ar' ? 'right' : 'left'}}>
                    <p className="fs-14 mb-1">{Translate[lang]?.orders} (<span className="text-danger">{Translate[lang]?.canceled}</span>)</p>
                    <span className="fs-32 text-black font-w600">
                    {formData.ordersCanceled}
                    </span>
                  </div>
                  <i className='la la-times text-danger' style={{fontSize: '2rem'}}></i>
                </div>
              </div>
            </div>
          </div>
          <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-center">
                  <div style={{ textAlign: lang=== 'ar' ? 'right' : 'left'}}>
                    <p className="fs-14 mb-1">{Translate[lang]?.orders} (<span className="text-success">{Translate[lang]?.delivered}</span>)</p>
                    <span className="fs-32 text-black font-w600">
                    {formData.ordersDelivered}
                    </span>
                  </div>
                  
                  <i className='la la-check-circle text-success' style={{fontSize: '2rem'}}></i>
                </div>
              </div>
            </div>
          </div>
          <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-center">
                  <div style={{ textAlign: lang=== 'ar' ? 'right' : 'left'}}>
                    <p className="fs-14 mb-1">{Translate[lang]?.total_sales} </p>
                    <span className="fs-32 text-black font-w600">
                    {formData.totalSales}
                    </span>
                  </div>
                  <i className='la la-dollar' style={{fontSize: '2rem'}}></i>
                </div>
              </div>
            </div>
          </div>
          <div className="col-md-3 col-sm-6">
            <div className="card">
              <div className="card-body">
                <div className="d-flex justify-content-between align-items-center">
                  <div style={{ textAlign: lang=== 'ar' ? 'right' : 'left'}}>
                    <p className="fs-14 mb-1">{Translate[lang]?.sales} ({Translate[lang]?.daily})</p>
                    <span className="fs-32 text-black font-w600">
                    {formData.salesDaily}
                    </span>
                  </div>
                  <i className='la la-dollar' style={{fontSize: '2rem'}}></i>
                </div>
              </div>
            </div>
          </div> */}
		</div>
	);
};

export default Home;
