import { useEffect, useState } from "react";
import { Badge } from "react-bootstrap";
import { Link, useNavigate } from "react-router-dom";
import DeleteModal from "../../../common/DeleteModal";
import AdminService from "../../../../services/AdminService";
import { useSelector } from "react-redux";
import { toast } from "react-toastify";
import { Translate } from "../../../Enums/Tranlate";
import editIcon from "../../../../images/icons/edit.svg";
import trashIcon from "../../../../images/icons/delete.svg";

const CardItem = ({ item, index, setShouldUpdate }) => {
	const [status, setStatus] = useState(null);
	const [deleteModal, setDeleteModal] = useState(false);
	const navigate = useNavigate();
	const adminService = new AdminService();
	const Auth = useSelector((state) => state.auth?.auth);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const lang = useSelector((state) => state.auth?.lang);

	useEffect(() => {
		setStatus(!item.isBlocked);
	}, [item]);

	const changeStatusToggle = (e) => {
		let data = {
			isBlocked: status,
		};
		adminService.toggleStatus(item.id, data).then((res) => {
			if (res?.status === 200) {
				toast.success(Translate[lang].updated_status_successfully);
				setStatus(!status);
			}
		});
	};

	return (
		<tr key={index}>
			<td>{item?.email}</td>

			<td>
				<Badge
					style={{ cursor: "pointer" }}
					onClick={() => navigate(`/rules/${item?.id}`)}
					variant={"outline-success"}>
					{item?.role?.name}
				</Badge>
			</td>
			<td>
				<div className="d-flex justify-content-center" style={{ gap: "20px" }}>
					{
						// isExist("update_role") ||
						<Link
							to={`/admins/edit-admin/${item.id}`}
							state={{ edit: true, id: item.id, item: item }}
							style={{
								color: "#0F50A6",
								fontWeight: "500",
							}}>
							<img src={editIcon} alt="view" width={24} />
						</Link>
					}
					{
						// isExist("delete_role") ||
						<img
							src={trashIcon}
							className="cursor-pointer"
							onClick={() => setDeleteModal(true)}
							alt="trash"
							width={24}
						/>
					}
				</div>
			</td>
			{deleteModal && (
				<DeleteModal
					open={deleteModal}
					titleMsg={item?.email}
					deletedItem={item}
					modelService={adminService}
					setShouldUpdate={setShouldUpdate}
					onCloseModal={setDeleteModal}
				/>
			)}
		</tr>
	);
};
export default CardItem;
