import BaseService from "./BaseService";
import http from "./HttpService";
import { API_BASE_URL_ENV } from "../jsx/common/common";

const apiEndpoint = API_BASE_URL_ENV() + "/admin/transport/requests";
const apiAssignEndpoint =
	API_BASE_URL_ENV() + "/admin/transport/requests/broker";

export default class TransportService extends BaseService {
	constructor() {
		super(apiEndpoint);
	}

	assignBroker(id, data) {
		const body = { ...data };
		return http.patch(`${apiAssignEndpoint}/${id}`, body);
	}
}
