import { useEffect, useState } from "react";
import { Badge, Button, Form } from "react-bootstrap";
import { Translate } from "../../../Enums/Tranlate";
import { useSelector } from "react-redux";
import UserService from "../../../../services/UserService";
import { toast } from "react-toastify";

const CardItem = ({ item, index }) => {
	const [status, setStatus] = useState(null);
	const lang = useSelector((state) => state.auth?.lang);
	const userService = new UserService();

	useEffect(() => {
		setStatus(item.isVerified);
	}, [item]);

	const approveUser = () => {
		userService.approveUser(item?.id).then((res) => {
			if (!!res?.status) {
				toast.success("User Approved Successfully");
				setStatus(true);
			}
		});
	};

	return (
		<tr key={index} className="text-center">
			<td>{item?.name || "-"}</td>
			<td>{item?.email || "-"}</td>
			<td>{item?.whatsappNumber || "-"}</td>
			<td>{Translate[lang][item?.userType?.toLocaleLowerCase()] || "-"}</td>
			<td>
				<Form.Check
					type="switch"
					id={`custom-switch${index}`}
					checked={status}
				/>
			</td>
			<td>
				{!status ? (
					<Badge
						variant="primary"
						className="cursor-pointer"
						onClick={() => {
							approveUser();
						}}>
						{Translate[lang].approve}
					</Badge>
				) : (
					<Badge variant="outline-primary">{Translate[lang].approved}</Badge>
				)}
			</td>
		</tr>
	);
};
export default CardItem;
