import { useState } from "react";
import { Button, Card, Table } from "react-bootstrap";
import { useSelector } from "react-redux";
import TransportService from "../../../services/TransportService";
import Loader from "../../common/Loader";
import NoData from "../../common/NoData";
import { Translate } from "../../Enums/Tranlate";
import CardItem from "./CardItem";
import CustomPagination from "../../common/CustomPagination";
import ViewModal from "./View";
// import FilterModal from "./FilterModal";

const Transport = () => {
	const [data, setData] = useState([]);
	const [hasData, setHasData] = useState(null);
	const [search, setSearch] = useState(null);
	const [shouldUpdate, setShouldUpdate] = useState(false);
	const [loading, setLoading] = useState(false);
	const lang = useSelector((state) => state?.auth.lang);
	const transportService = new TransportService();
	const [item, setItem] = useState({});
	const [params, setParams] = useState({});
	const [filterModal, setFilterModal] = useState(false);
	const [modal, setModal] = useState(false);

	return (
		<>
			<Card>
				<Card.Body className={`${hasData === 0 && "text-center"} `}>
					<div className="mb-3 d-flex justify-content-between">
						<div className="tabs-div d-flex">
							<span
								className={!params?.transportType ? "active" : ""}
								onClick={() => {
									setParams({});
									setShouldUpdate((prev) => !prev);
								}}>
								{Translate[lang].all}
							</span>

							<span
								className={params?.transportType === "EXPORT" ? "active" : ""}
								onClick={() => {
									setParams({ transportType: "EXPORT" });
									setShouldUpdate((prev) => !prev);
								}}>
								{Translate[lang].export}
							</span>
							<span
								className={params?.transportType === "IMPORT" ? "active" : ""}
								onClick={() => {
									setParams({ transportType: "IMPORT" });
									setShouldUpdate((prev) => !prev);
								}}>
								{Translate[lang].import}
							</span>
							<span
								className={params?.transportType === "DOMESTIC" ? "active" : ""}
								onClick={() => {
									setParams({ transportType: "DOMESTIC" });
									setShouldUpdate((prev) => !prev);
								}}>
								{Translate[lang].domestic}
							</span>
						</div>
						{/* <Button
							variant="outline-primary"
							onClick={() => setFilterModal(true)}>
							{Translate[lang].filter}
						</Button> */}
					</div>
					{loading && (
						<div style={{ height: "300px" }}>
							<Loader />
						</div>
					)}
					{hasData === 1 && !loading && (
						<Table responsive bordered hover>
							<thead>
								<tr className="text-center">
									<th>
										<strong>{Translate[lang]?.user}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.email}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.user_type}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.broker}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.type}</strong>
									</th>
									{/* <th>
										<strong>{Translate[lang]?.number_of_containers}</strong>
									</th> */}
									<th>
										<strong>{Translate[lang]?.loading_governorate}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.loading_area}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.unloading_governorate}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.unloading_area}</strong>
									</th>
									{params?.transportType !== "DOMESTIC" && (
										<th>
											<strong>{Translate[lang]?.port}</strong>
										</th>
									)}
									<th>
										<strong>{Translate[lang]?.status}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.actions}</strong>
									</th>
								</tr>
							</thead>
							<tbody>
								{data?.map((item, index) => {
									return (
										<CardItem
											key={index}
											index={index}
											item={item}
											type={params?.transportType}
											setItem={setItem}
											setShouldUpdate={setShouldUpdate}
										/>
									);
								})}
							</tbody>
						</Table>
					)}

					{hasData === 0 && <NoData />}

					<CustomPagination
						setData={setData}
						service={transportService}
						shouldUpdate={shouldUpdate}
						setHasData={setHasData}
						setLoading={setLoading}
						search={search}
						param={params}
					/>
				</Card.Body>
			</Card>
			{/* {filterModal && (
				<FilterModal
					modal={filterModal}
					setModal={setFilterModal}
					params={params}
					setParams={setParams}
				/>
			)} */}
		</>
	);
};
export default Transport;
