import { Badge } from "react-bootstrap";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import { useState } from "react";
import AssignModal from "../../../common/AssignModal";

const CardItem = ({ item, index, setShouldUpdate }) => {
	const [assign, setAssign] = useState(false);
	const status = item?.status;
	const lang = useSelector((state) => state.auth?.lang);

	return (
		<tr key={index} className="text-center">
			<td>
				<strong>{item?.user?.name}</strong>
			</td>
			<td>{item?.user?.email}</td>
			<td>{Translate[lang][item?.user?.userType?.toLocaleLowerCase()]}</td>
			<td>{!!item?.brokerId ? item?.broker?.name : "-"}</td>
			<td>
				<Badge variant="outline-primary">
					{Translate[lang][item?.clearanceType?.toLocaleLowerCase()]}
				</Badge>
			</td>
			<td>
				<a href={item?.officialDocumentsUrl} target="_blank" rel="noreferrer">
					<i className="la la-file-pdf" style={{ fontSize: "2rem" }} />
				</a>
			</td>
			<td>
				<Badge
					variant={
						status === "completed"
							? "primary"
							: status === "in_progress"
							? "success"
							: status === "pending"
							? "warning"
							: "danger"
					}>
					{Translate[lang][status?.toLocaleLowerCase()]}
				</Badge>
			</td>
			<td>
				<Badge
					onClick={() => setAssign(true)}
					className="cursor-pointer"
					variant="primary">
					{!item?.brokerId ? Translate[lang].assign : Translate[lang].reassign}
				</Badge>
			</td>
			{assign && (
				<AssignModal
					assign={assign}
					setAssign={setAssign}
					setShouldUpdate={setShouldUpdate}
					item={item}
					type="clearance"
				/>
			)}
		</tr>
	);
};
export default CardItem;
