import BaseService from "./BaseService";
import http from "./HttpService";
import { API_BASE_URL_ENV } from "../jsx/common/common";

const apiEndpoint = API_BASE_URL_ENV() + "/brokers/requests";

export default class BrokerBrokerService extends BaseService {
	constructor() {
		super(apiEndpoint);
	}

	updateStatus(id, type, data) {
		const body = { ...data };
		return http.patch(`${apiEndpoint}/${type}/${id}/status`, body);
	}
}
