import React, { useEffect, useState } from "react";
import {
	Routes,
	Route,
	Outlet,
	useLocation,
	useNavigate,
} from "react-router-dom";
/// Css
import "./index.css";
import "./chart.css";
import "./step.css";

/// Layout
import Nav from "./layouts/nav";
import Footer from "./layouts/Footer";

/// Pages
import Error404 from "./common/Error404";

//Scroll To Top
import ScrollToTop from "./layouts/ScrollToTop";

import Admins from "./pages/Admin";
import AddAdmin from "./pages/Admin/AddAdmin";
import Static from "./pages/Setting/StaticPages/Static";
import Notification from "./pages/Notification";
import AddNotification from "./pages/Notification/AddNotification";
import Home from "./pages/Dashboard";
import Users from "./pages/Users";
import Permission from "./pages/Roles";
import AddPermission from "./pages/Roles/AddRole";
import Broker from "./pages/Broker";
import BrokerBroker from "./pages/BrokerBroker";
import { useSelector } from "react-redux";
import Transport from "./pages/Transport";
import Clearance from "./pages/Clearance";
import View from "./pages/Transport/View";

const Markup = () => {
	const [type, setType] = useState("");
	const location = useLocation();
	const navigate = useNavigate();
	const Auth = useSelector((state) => state?.auth?.auth);

	useEffect(() => {
		setType(Auth?.type);
	}, [location]);

	const allroutes = [
		/// Dashboard
		{ url: "", component: <Home /> },
		{ url: "dashboard", component: <Home /> },

		// Admins
		{ url: "admins", component: <Admins /> },
		{ url: "admins/add-admins", component: <AddAdmin /> },
		{ url: "admins/edit-admin/:id", component: <AddAdmin /> },

		// Users
		{ url: "users", component: <Users /> },
		// { url: "users/profile", component: <UserProfile /> },

		// Rules
		{ url: "roles", component: <Permission /> },
		{ url: "roles/add_role", component: <AddPermission /> },
		{ url: "roles/:id", component: <AddPermission /> },

		{ url: "broker-managment", component: <Broker /> },

		// Transport
		{ url: "transport", component: <Transport /> },
		{ url: "transport/:id", component: <View /> },

		// Clearance
		{ url: "clearance", component: <Clearance /> },

		//  => Notification
		// { url: "notification", component: <Notification /> },
		{ url: "notification", component: <AddNotification /> },

		//  => Setting
		{ url: "static-pages", component: <Static /> },

		// Error
		{ url: "*", component: <Error404 /> },
	];

	const brokerRoutes = [
		/// Dashboard
		{ url: "", component: <BrokerBroker /> },
		{ url: "/:type", component: <BrokerBroker /> },

		// Error
		{ url: "*", component: <Error404 /> },
	];

	return (
		<>
			<Routes>
				<Route path="page-error-404" element={<Error404 />} />
				<Route element={<MainLayout />}>
					{type === "admin" &&
						allroutes.map((data, i) => (
							<Route
								key={i}
								exact
								path={`${data.url}`}
								element={data.component}
							/>
						))}
					{type === "broker" &&
						brokerRoutes.map((data, i) => (
							<Route
								key={i}
								exact
								path={`${data.url}`}
								element={data.component}
							/>
						))}
				</Route>
			</Routes>
			<ScrollToTop />
		</>
	);
};

function MainLayout() {
	return (
		<div id="main-wrapper" className={`show `}>
			<Nav />
			<div
				className="content-body"
				style={{ minHeight: window.screen.height - 45 }}>
				<div>
					<Outlet />
				</div>
			</div>
			<Footer />
		</div>
	);
}

export default Markup;
