import BaseService from "./BaseService";
import http from "./HttpService";
import { API_BASE_URL_ENV } from "../jsx/common/common";

const apiEndpoint = API_BASE_URL_ENV() + "/admin/brokers";

export default class BrokerService extends BaseService {
	constructor() {
		super(apiEndpoint);
	}

	update(id, data) {
		const body = { ...data };
		return http.patch(`${apiEndpoint}/${id}`, body);
	}

	updateStatus(id, data) {
		const body = { ...data };
		return http.patch(`${apiEndpoint}/${id}/status`, body);
	}
}
