import { Badge, Button, Card, Col, Row, Table } from "react-bootstrap";
import "./style.css";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import React, { useEffect, useState } from "react";
import TransportService from "../../../../services/TransportService";
import { useLocation, useNavigate } from "react-router-dom";

const View = () => {
	const [data, setData] = useState({});
	const [loading, setLoading] = useState(false);
	const location = useLocation();
	const navigate = useNavigate();
	const lang = useSelector((state) => state.auth.lang);
	const transportService = new TransportService();

	useEffect(() => {
		if (location?.state) {
			setLoading(true);
			transportService.find(location?.state?.id).then((res) => {
				setLoading(false);
				if (res?.status === 200) {
					setData(res?.data?.data);
				}
			});
		}
	}, []);

	if (loading) {
		return <></>;
	}

	return (
		<Card className={`p-0 view-req ${lang}`}>
			<Card.Body>
				<Row>
					<Col md={6}>
						<Badge variant="primary">
							{Translate[lang][data?.transportType?.toLocaleLowerCase()]}
						</Badge>
					</Col>
					<Col md={6}>
						<Badge
							variant={
								data?.status === "pending" ? "outline-info" : "outline-danger"
							}>
							{Translate[lang][data?.status]}
						</Badge>
					</Col>
					<Col md={12}>
						<hr />
					</Col>
					<Col md={6}>
						<label className="mb-0">{Translate[lang].broker}:</label>
						<p>{data?.broker?.name}</p>
					</Col>
					<Col md={6}>
						<label className="mb-0">
							{Translate[lang].broker} {Translate[lang].email}:
						</label>
						<p>{data?.broker?.email}</p>
					</Col>
					<Col md={12}>
						<hr />
					</Col>
					<Col md={12}>
						<h4>{Translate[lang].containers}</h4>
					</Col>
					<Col md={5}>
						<Table responsive bordered hover>
							<thead>
								<tr className="text-center">
									<th className="py-2">
										<strong>{Translate[lang]?.quantity}</strong>
									</th>
									<th className="py-2">
										<strong>{Translate[lang]?.container_size}</strong>
									</th>
								</tr>
							</thead>
							<tbody>
								{data?.containers?.map((res, index) => {
									return (
										<tr key={index} className="text-center">
											<td className="py-2">{res?.quantity || "-"}</td>
											<td className="py-2">{res?.containerSize || "-"}</td>
										</tr>
									);
								})}
							</tbody>
						</Table>
					</Col>
					<Col md={7}></Col>
					<Col md={12}>
						<hr />
					</Col>
					<Col md={6}>
						<label className="mb-0">{Translate[lang].user}:</label>
						<p>{data?.user?.name}</p>
					</Col>
					<Col md={6}>
						<label className="mb-0">
							{Translate[lang].user} {Translate[lang].email}:
						</label>
						<p>{data?.user?.email}</p>
					</Col>
					<Col md={12}>
						<hr />
					</Col>
					{data?.transportType !== "IMPORT" && (
						<>
							<Col md={6}>
								<label className="mb-0">
									{Translate[lang].loading_governorate}:
								</label>
								<p>{data?.loadingGovernorate}</p>
							</Col>
							<Col md={6}>
								<label className="mb-0">{Translate[lang].loading_area}:</label>
								<p>{data?.loadingArea}</p>
							</Col>
							<Col md={12}>
								<hr />
							</Col>
						</>
					)}
					{data?.transportType !== "EXPORT" && (
						<>
							<Col md={6}>
								<label className="mb-0">
									{Translate[lang].unloading_governorate}:
								</label>
								<p>{data?.unloadingGovernorate}</p>
							</Col>
							<Col md={6}>
								<label className="mb-0">
									{Translate[lang].unloading_area}:
								</label>
								<p>{data?.unloadingArea}</p>
							</Col>
							<Col md={12}>
								<hr />
							</Col>
						</>
					)}
					{data?.transportType !== "DOMESTIC" && (
						<>
							<Col md={12}>
								<label className="mb-0">{Translate[lang].port}:</label>
								<p>{data?.port}</p>
							</Col>
							<Col md={12}>
								<hr />
							</Col>
						</>
					)}
					<Col md={12}>
						<label className="mb-0">{Translate[lang].note}:</label>
						<p>{data?.requestNotes}</p>
					</Col>
					<Col md={12}>
						<hr />
					</Col>
				</Row>

				<Button
					variant="danger"
					className="mt-3 px-5"
					onClick={() => navigate("/transport")}>
					{Translate[lang].cancel}
				</Button>
			</Card.Body>
		</Card>
	);
};
export default View;
