import React, { Fragment } from "react";
import { useState } from "react";
import { Row, Col, Card, Table } from "react-bootstrap";
import { useSelector } from "react-redux";
import Loader from "../../common/Loader";
import NoData from "../../common/NoData";
import { Translate } from "../../Enums/Tranlate";
import CardItem from "./CardItem";
import "./style.scss";
import BrokerService from "../../../services/BrokerBrokerService";
import { useLocation } from "react-router-dom";
import StatusModal from "./StatusModal";
import CustomPagination from "../../common/CustomPagination";

const BrokerBroker = () => {
	const [data, setData] = useState([]);
	const [statusModal, setStatusModal] = useState(false);
	const [item, setItem] = useState({});
	const [hasData, setHasData] = useState(null);
	const [shouldUpdate, setShouldUpdate] = useState(false);
	const [loading, setLoading] = useState(false);
	const lang = useSelector((state) => state.auth?.lang);
	const brokerService = new BrokerService();
	const location = useLocation();
	const type = location?.pathname?.includes("clearance")
		? "clearance"
		: "transport";

	return (
		<Fragment>
			<Card className="mb-4">
				<Card.Body className="p-3">
					<div className="d-flex justify-content-between align-items-center">
						<div className="input-group w-50">
							<div>
								<span
									style={{
										fontWeight: "600",
										textTransform: "capitalize",
										color: "#000",
									}}>
									{Translate[lang].broker_managment}
								</span>
							</div>
						</div>
					</div>
				</Card.Body>
			</Card>
			<Row>
				<Col lg={12}>
					<Card>
						<Card.Body className={`${hasData === 0 && "text-center"} `}>
							{loading && (
								<div style={{ height: "300px" }}>
									<Loader />
								</div>
							)}
							{hasData === 1 && !loading && (
								<Table responsive bordered hover>
									<thead>
										<tr className="text-center">
											<th>
												<strong>{Translate[lang]?.name}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.email}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.user_type}</strong>
											</th>
											{type === "clearance" && (
												<th>
													<strong>{Translate[lang]?.clearance_type}</strong>
												</th>
											)}
											{type === "clearance" && (
												<th>
													<strong>{Translate[lang]?.document}</strong>
												</th>
											)}

											{type === "transport" && (
												<th>
													<strong>{Translate[lang]?.type}</strong>
												</th>
											)}
											{type === "transport" && (
												<th>
													<strong>
														{Translate[lang]?.number_of_containers}
													</strong>
												</th>
											)}
											{type === "transport" && (
												<th>
													<strong>
														{Translate[lang]?.loading_governorate}
													</strong>
												</th>
											)}
											{type === "transport" && (
												<th>
													<strong>{Translate[lang]?.loading_area}</strong>
												</th>
											)}
											{type === "transport" && (
												<th>
													<strong>
														{Translate[lang]?.unloading_governorate}
													</strong>
												</th>
											)}
											{type === "transport" && (
												<th>
													<strong>{Translate[lang]?.unloading_area}</strong>
												</th>
											)}
											<th>
												<strong>{Translate[lang]?.status}</strong>
											</th>
										</tr>
									</thead>

									<tbody className="table-body">
										{data?.map((item, index) => {
											return (
												<CardItem
													index={index}
													key={index}
													item={item}
													type={type}
													setItem={setItem}
													setStatusModal={setStatusModal}
													setShouldUpdate={setShouldUpdate}
												/>
											);
										})}
									</tbody>
								</Table>
							)}
							{hasData === 0 && <NoData />}
							<CustomPagination
								setData={setData}
								service={brokerService}
								shouldUpdate={shouldUpdate}
								setHasData={setHasData}
								setLoading={setLoading}
								type={type === "clearance" ? "CLEARANCE" : "TRANSPORT"}
							/>
						</Card.Body>
					</Card>
				</Col>
			</Row>

			{statusModal && (
				<StatusModal
					item={item}
					statusModal={statusModal}
					setShouldUpdate={setShouldUpdate}
					type={type}
					setStatusModal={() => setStatusModal(false)}
				/>
			)}
		</Fragment>
	);
};

export default BrokerBroker;
