import { Badge } from "react-bootstrap";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";

const CardItem = ({ item, setItem, index, setStatusModal, type }) => {
	const status = item?.status;
	const lang = useSelector((state) => state.auth?.lang);

	return (
		<tr key={index} className="text-center">
			<td>
				<strong>{item?.user?.name}</strong>
			</td>
			<td>{item?.user?.email}</td>
			<td>{Translate[lang][item?.user?.userType?.toLocaleLowerCase()]}</td>
			{type === "clearance" && (
				<td>
					<Badge variant="outline-primary">
						{Translate[lang][item?.clearanceType?.toLocaleLowerCase()]}
					</Badge>
				</td>
			)}
			{type === "clearance" && (
				<td>
					<a href={item?.officialDocumentsUrl} target="_blank" rel="noreferrer">
						<i className="la la-file-pdf" style={{ fontSize: "2rem" }} />
					</a>
				</td>
			)}
			{type === "transport" && (
				<td>
					<Badge variant="outline-primary">
						{Translate[lang][item?.transportType?.toLocaleLowerCase()]}
					</Badge>
				</td>
			)}
			{type === "transport" && <td>{item?.numberOfContainers}</td>}
			{type === "transport" && (
				<td className="text-nowrap">{item?.loadingGovernorate}</td>
			)}
			{type === "transport" && (
				<td className="text-nowrap">{item?.loadingArea}</td>
			)}
			{type === "transport" && (
				<td className="text-nowrap">{item?.unloadingGovernorate}</td>
			)}
			{type === "transport" && (
				<td className="text-nowrap">{item?.unloadingArea}</td>
			)}
			<td>
				<Badge
					className="cursor-pointer"
					variant={
						status === "completed"
							? "primary"
							: status === "in_progress"
							? "success"
							: status === "pending"
							? "warning"
							: "danger"
					}
					onClick={() => {
						setStatusModal(true);
						setItem(item);
					}}>
					{Translate[lang][status?.toLocaleLowerCase()]}
				</Badge>
			</td>
		</tr>
	);
};
export default CardItem;
