import { Button, Card, Col, Row } from "react-bootstrap";
import { AvForm } from "availity-reactstrap-validation";
import { EditorState, convertToRaw, ContentState } from "draft-js";
import { useEffect, useState } from "react";
import { Editor } from "react-draft-wysiwyg";
import draftToHtml from "draftjs-to-html";
import htmlToDraft from "html-to-draftjs";
import "react-draft-wysiwyg/dist/react-draft-wysiwyg.css";
import "draft-js/dist/Draft.css";
import { toast } from "react-toastify";
import { useSelector } from "react-redux";
import { Translate } from "../../../../Enums/Tranlate";
import Loader from "../../../../common/Loader";
import { useLocation } from "react-router-dom";
import "../style.scss";
import StaticPagesServices from "../../../../../services/StaticPagesService";

const Static = () => {
	const [formData, setFormData] = useState([
		{
			type: "TERMS",
			contentEn: EditorState.createEmpty(),
			contentAr: EditorState.createEmpty(),
		},
		{
			type: "PRIVACY_POLICY",
			contentEn: EditorState.createEmpty(),
			contentAr: EditorState.createEmpty(),
		},
		{
			type: "ABOUT_US",
			contentEn: EditorState.createEmpty(),
			contentAr: EditorState.createEmpty(),
		},
	]);
	const Auth = useSelector((state) => state.auth?.auth);
	const lang = useSelector((state) => state.auth.lang);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const [loading, setLoading] = useState();
	const location = useLocation();
	const [submitLoading, setSubmitLoading] = useState(false);
	const staticPagesServices = new StaticPagesServices();

	useEffect(() => {
		setLoading(true);
		staticPagesServices.getList().then((res) => {
			if (res?.status === 200 && !!res.data.data?.length) {
				let data = res.data.data?.map((item) => {
					return {
						type: item?.type,
						contentEn: EditorState.createWithContent(
							ContentState.createFromBlockArray(htmlToDraft(item.contentEn))
						),
						contentAr: EditorState.createWithContent(
							ContentState.createFromBlockArray(htmlToDraft(item.contentAr))
						),
					};
				});
				setFormData(data);
			}
			setLoading(false);
		});
	}, [location?.pathname]);

	const submit = (info) => {
		let data = {
			contentEn: draftToHtml(convertToRaw(info.contentEn.getCurrentContent())),
			contentAr: draftToHtml(convertToRaw(info.contentAr.getCurrentContent())),
		};
		setSubmitLoading(true);
		staticPagesServices.update(info.type, data).then((res) => {
			if (!!res?.status) {
				toast.success("Update Data Successfullly");
			}
			setSubmitLoading(false);
		});
	};

	if (loading) {
		return (
			<Card className="py-5" style={{ height: "300px" }}>
				<Card.Body>
					<Loader />
				</Card.Body>
			</Card>
		);
	}

	return (
		<>
			{formData?.map((res, index) => {
				return (
					<Card key={res.type}>
						<Card.Body>
							<h3 className="mb-0">
								{Translate[lang][res?.type?.toLocaleLowerCase()]}
							</h3>
							<hr />
							<AvForm onValidSubmit={() => submit(res)} className="about-us">
								<Row className="position-relative">
									<Col
										md={6}
										className="form-group"
										style={{ marginBottom: "8rem" }}>
										<label className="d-block">
											{Translate[lang].english_description}
										</label>
										<div className="editorField">
											<Editor
												editorState={res.contentEn}
												toolbarClassName="toolbarClassName"
												wrapperClassName="wrapperClassName"
												editorClassName="editorClassName"
												onEditorStateChange={(e) => {
													setFormData((prev) =>
														prev?.map((info, ind) =>
															index === ind ? { ...info, contentEn: e } : info
														)
													);
												}}
											/>
										</div>
									</Col>
									<Col
										md={6}
										className="form-group"
										style={{ marginBottom: "8rem" }}>
										<label className="d-block">
											{Translate[lang].arabic_description}
										</label>
										<div className="editorField">
											<Editor
												editorState={res.contentAr}
												toolbarClassName="toolbarClassName"
												wrapperClassName="wrapperClassName"
												editorClassName="editorClassName"
												onEditorStateChange={(e) => {
													setFormData((prev) =>
														prev?.map((info, ind) =>
															index === ind ? { ...info, contentAr: e } : info
														)
													);
												}}
											/>
										</div>
									</Col>
								</Row>

								{isExist("static_pages") ||
									(true && (
										<div className="d-flex justify-content-between">
											<div></div>
											<Button
												variant="primary"
												className="px-5"
												disabled={submitLoading}
												type="submit">
												{Translate[lang].submit}
											</Button>
										</div>
									))}
							</AvForm>
						</Card.Body>
					</Card>
				);
			})}
		</>
	);
};
export default Static;
