import axios from "axios";
import https from "https";
import { toast } from "react-toastify";
import swal from "sweetalert";
import { Logout } from "../store/actions/AuthActions";

axios.defaults.headers.common["Content-Type"] = "application/json";
axios.defaults.headers.common["Accept"] = "application/json";
axios.defaults.httpsAgent = new https.Agent({ rejectUnauthorized: false });
function setInterceptors(navigate) {
	axios.interceptors.response.use(null, async (error) => {
		if (
			error?.response?.data?.message === "Unauthorized" ||
			error?.response?.data?.message === "not_authorized" ||
			error?.response?.data?.message === "not_authorized_old_Token" ||
			error?.response?.data?.message === "غير مصرح به (رمز قديم)"
		) {
			Logout();
		} else if (
			error?.response?.data?.message === "المستخدم غير موجود" ||
			error?.response?.data?.message === "Email or password is incorrect"
		) {
			swal("Oops", "Email or password is incorrect", "error", {
				button: "Try Again!",
			});
		} else if (!!error?.response?.data?.errors?.length) {
			error?.response?.data?.errors?.map((res) =>
				toast.error(`${res?.message}`)
			);
			return;
		} else {
			toast.error(error.message);
		}
	});
}

function setJwt(jwt) {
	axios.defaults.headers.common["Authorization"] = `Bearer ${jwt}`;
}
const obj = {
	get: axios.get,
	post: axios.post,
	put: axios.put,
	delete: axios.delete,
	patch: axios.patch,
	setJwt,
	setInterceptors,
};
export default obj;
