import BaseService from "./BaseService";
import http from "./HttpService";
import { API_BASE_URL_ENV } from "../jsx/common/common";

const apiEndpoint = API_BASE_URL_ENV() + "/admin/roles";
const apiGetModuleEndpoint = API_BASE_URL_ENV() + "/admin/permissions";

export default class RoleService extends BaseService {
	constructor() {
		super(apiEndpoint);
	}

	getModule = () => {
		return http.get(apiGetModuleEndpoint);
	};
	update = (id, data) => {
		return http.get(`${apiEndpoint}/${id}/permissions`, data);
	};
}
