import { useEffect, useState } from "react";
import { Button, Col, Modal, Row } from "react-bootstrap";
import { AvField, AvForm } from "availity-reactstrap-validation";
import { toast } from "react-toastify";
import Select from "react-select";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import BrokerService from "../../../../services/BrokerService";

const AddBrokerModal = ({ addModal, setAddModal, item, setShouldUpdate }) => {
	const lang = useSelector((state) => state.auth?.lang);
	const typesOptions = [
		{ label: Translate[lang].clearance, value: "CLEARANCE" },
		{ label: Translate[lang].transport, value: "TRANSPORT" },
	];
	const [showPassword, setShowPassword] = useState(false);
	const [formData, setFormData] = useState({
		name: "",
		email: "",
		password: "",
		types: "",
		capacity: "",
	});
	const [isAdd, setIsAdd] = useState(false);
	const [loading, setLoading] = useState(false);
	const brokerService = new BrokerService();

	useEffect(() => {
		if (Object.keys(item)?.length === 0) {
			setIsAdd(true);
		} else {
			setIsAdd(false);
			setFormData({
				id: item?.id,
				name: item?.name,
				email: item?.email,
				capacity: item?.capacity,
				types: item?.types?.map((res) => {
					return {
						label: Translate[lang][res?.toLocaleLowerCase()],
						value: res,
					};
				}),
			});
		}
	}, [item]);

	const submit = () => {
		let data = {
			name: formData?.name,
			email: formData?.email,
			capacity: Number(formData?.capacity),
			types: formData?.types?.map((res) => res?.value),
		};
		data["password"] = formData?.password;

		if (isAdd) {
			brokerService.create(data)?.then((res) => {
				if (res && res?.status === 201) {
					toast.success("Broker Added Successfully");
					setAddModal();
					setShouldUpdate((prev) => !prev);
				}
			});
		} else {
			brokerService.update(formData?.id, data)?.then((res) => {
				if (res && res?.status === 200) {
					toast.success("Broker Updated Successfully");
					setAddModal();
					setShouldUpdate((prev) => !prev);
				}
			});
		}
	};

	return (
		<Modal
			className={lang === "en" ? "en fade" : "ar fade"}
			style={{ textAlign: lang === "en" ? "left" : "right" }}
			show={addModal}
			onHide={() => {
				setAddModal();
			}}>
			<AvForm className="form-horizontal" onValidSubmit={submit}>
				<Modal.Header>
					<Modal.Title>
						{isAdd ? Translate[lang]?.add : Translate[lang]?.edit}{" "}
						{Translate[lang]?.broker}
					</Modal.Title>
					<Button
						variant=""
						className="close"
						style={{
							right: lang === "en" ? "0" : "auto",
							left: lang === "ar" ? "0" : "auto",
						}}
						onClick={() => {
							setAddModal();
						}}>
						<span>&times;</span>
					</Button>
				</Modal.Header>
				<Modal.Body>
					<Row>
						<Col md={12}>
							<AvField
								label={Translate[lang]?.name}
								type="text"
								placeholder={Translate[lang]?.name}
								bsSize="lg"
								name="name"
								validate={{
									required: {
										value: true,
										errorMessage: Translate[lang].field_required,
									},
								}}
								value={formData.name}
								onChange={(e) =>
									setFormData({ ...formData, name: e.target.value })
								}
							/>
						</Col>
						<Col md={12}>
							<AvField
								label={Translate[lang]?.email}
								type="email"
								placeholder={Translate[lang]?.email}
								bsSize="lg"
								name="email"
								validate={{
									required: {
										value: true,
										errorMessage: Translate[lang].field_required,
									},
								}}
								value={formData.email}
								onChange={(e) =>
									setFormData({ ...formData, email: e.target.value })
								}
							/>
						</Col>
						<Col md={6}>
							<AvField
								label={`${Translate[lang]?.password}`}
								name="password"
								type={`${showPassword ? "password" : "text"}`}
								value={formData?.password}
								errorMessage="Please enter a valid Password"
								validate={{
									required: {
										value: !formData?.id,
										errorMessage: Translate[lang].field_required,
									},
								}}
								onFocus={(e) => setShowPassword(false)}
								onBlur={(e) => setShowPassword(true)}
								placeholder={`${Translate[lang]?.password}`}
								onChange={(e) =>
									setFormData({ ...formData, password: e.target.value })
								}
							/>
						</Col>
						<Col md={6}>
							<AvField
								label={Translate[lang]?.capacity}
								type="number"
								placeholder={Translate[lang]?.capacity}
								bsSize="lg"
								name="capacity"
								validate={{
									required: {
										value: true,
										errorMessage: Translate[lang].field_required,
									},
								}}
								value={formData.capacity}
								onChange={(e) =>
									setFormData({ ...formData, capacity: e.target.value })
								}
							/>
						</Col>
						<Col md={12} className="mb-3">
							<label className="text-label">{Translate[lang].types}</label>
							<Select
								value={formData?.types}
								name="types"
								placeholder={Translate[lang].select}
								options={typesOptions}
								isMulti
								onChange={(e) => setFormData({ ...formData, types: e })}
							/>
						</Col>
					</Row>
				</Modal.Body>
				<Modal.Footer>
					<Button onClick={setAddModal} variant="danger light">
						{Translate[lang]?.close}
					</Button>
					<Button variant="primary" type="submit" disabled={loading}>
						{isAdd ? Translate[lang]?.add : Translate[lang]?.edit}
					</Button>
				</Modal.Footer>
			</AvForm>
		</Modal>
	);
};

export default AddBrokerModal;
