import { useRef, useState } from "react";
import { Button, Card, Col, Modal, Row } from "react-bootstrap";
import { AvField, AvForm } from "availity-reactstrap-validation";
import { toast } from "react-toastify";
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import NotificationService from "../../../../services/NotificationService";

const AddNotification = () => {
	const [formData, setFormData] = useState({
		title: "",
		titleAr: "",
	});
	const formRef = useRef(null);
	const [loading, setLoading] = useState(false);
	const navigate = useNavigate();
	const notificationService = new NotificationService();
	const lang = useSelector((state) => state.auth.lang);

	const submit = () => {
		// if(!formData?.description_en || !formData?.description_ar){
		//     toast.error('Enter Message First')
		//     return
		// }
		let data = {
			title: formData?.title,
			titleAr: formData?.titleAr,
		};
		setLoading(true);
		notificationService.create(data)?.then((res) => {
			if (res?.status === 200) {
				toast.success("Notification Added Successfully");
				setLoading(false);
				formRef.current.reset();
				setFormData({
					title: "",
					titleAr: "",
				});
			}
		});
	};

	return (
		<Card>
			<AvForm ref={formRef} className="form-horizontal" onValidSubmit={submit}>
				<Card.Body>
					<Row>
						<Col md={6}>
							<AvField
								label={Translate[lang].english_title}
								type="text"
								placeholder={Translate[lang].english_title}
								bsSize="lg"
								name="title"
								validate={{
									required: {
										value: true,
										errorMessage: Translate[lang].field_required,
									},
								}}
								value={formData.title}
								onChange={(e) =>
									setFormData({ ...formData, title: e.target.value })
								}
							/>
						</Col>
						<Col md={6}>
							<AvField
								label={Translate[lang].arabic_title}
								type="text"
								placeholder={Translate[lang].arabic_title}
								value={formData.titleAr}
								name="titleAr"
								validate={{
									required: {
										value: true,
										errorMessage: Translate[lang].field_required,
									},
								}}
								onChange={(e) =>
									setFormData({ ...formData, titleAr: e.target.value })
								}
							/>
						</Col>
					</Row>
				</Card.Body>
				<Modal.Footer className="justify-content-between">
					<div></div>
					<Button variant="primary" type="submit" disabled={loading}>
						{Translate[lang].send}
					</Button>
				</Modal.Footer>
			</AvForm>
		</Card>
	);
};

export default AddNotification;
