import React, { useEffect, useState } from "react";
import { Button, Card } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import AdminService from "../../../../services/AdminService";
import { useLocation } from "react-router-dom";
import Select from "react-select";
import { AvField, AvForm } from "availity-reactstrap-validation";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import RoleService from "../../../../services/RoleService";

const AddAdmin = () => {
	const location = useLocation();
	const [formData, setFormData] = useState({
		name: "",
		email: "",
		password: "",
		role: "",
	});
	const [loading, setLoading] = useState(false);
	const [showPassword, setShowPassword] = useState(false);
	const [rolesOptions, setRolesOptions] = useState([]);
	const navigate = useNavigate();
	const adminService = new AdminService();
	const roleService = new RoleService();
	const lang = useSelector((state) => state.auth?.lang);

	useEffect(() => {
		roleService.getList().then((res) => {
			if (res?.status) {
				const response = res?.data?.data?.map((rol) => {
					return {
						label: rol?.name,
						value: rol?.id,
						id: rol?.id,
					};
				});
				setRolesOptions(response);
			}
		});

		if (location?.state?.edit) {
			let item = location.state?.item;
			setFormData({
				// name: item?.name,
				email: item?.email,
				password: "",
				role: {
					label: item?.role?.name,
					value: item?.role?.id,
					id: item?.role?.id,
				},
			});
		}
	}, []);

	const inputHandler = (e) => {
		setFormData({ ...formData, [e.target.name]: e.target.value });
	};

	const onSubmit = (e) => {
		e.preventDefault();
		let data = {
			email: formData?.email,
			roleId: formData.role?.value,
			password: formData?.password,
		};

		if (location?.state?.edit) {
			if (!!formData?.password) data["password"] = formData?.password;
			setLoading(true);
			adminService.update(location.state?.id, data).then((response) => {
				if (response?.status === 200) {
					toast.success("Admin Updated Successfully");
					navigate("/admins");
				}
				setLoading(false);
			});
		} else {
			data["password"] = formData?.password;

			setLoading(true);
			adminService.create(data).then((response) => {
				if (response?.status === 201) {
					toast.success(
						`${Translate[lang].added} ${Translate[lang].admin} ${Translate[lang].successfully}`
					);
					navigate("/admins");
				}
				setLoading(false);
			});
		}
	};

	return (
		<Card className="p-4">
			<AvForm onValidSubmit={onSubmit}>
				<div className="row">
					{/* <div className="col-lg-6 col-sm-6 mb-3">
						<AvField
							label={`${Translate[lang]?.name}`}
							name="name"
							type="text"
							value={formData?.name}
							errorMessage="Please enter a valid Name"
							validate={{
								required: {
									value: true,
									errorMessage: Translate[lang].field_required,
								},
							}}
							placeholder={`${Translate[lang]?.name}`}
							onChange={(e) => inputHandler(e)}
						/>
					</div> */}
					<div className="col-lg-6 col-sm-6 mb-3">
						<AvField
							label={`${Translate[lang]?.email}`}
							name="email"
							type="email"
							value={formData?.email}
							errorMessage="Please enter a valid Email"
							validate={{
								required: {
									value: true,
									errorMessage: Translate[lang].field_required,
								},
							}}
							placeholder="example@example.com"
							onChange={(e) => inputHandler(e)}
						/>
					</div>
					<div className="col-lg-6 col-sm-6 mb-3">
						<AvField
							label={`${Translate[lang]?.password}`}
							name="password"
							type={`${showPassword ? "password" : "text"}`}
							value={formData?.password}
							errorMessage="Please enter a valid Password"
							validate={{
								required: {
									value: !location?.state?.edit,
									errorMessage: Translate[lang].field_required,
								},
							}}
							onFocus={(e) => setShowPassword(false)}
							onBlur={(e) => setShowPassword(true)}
							placeholder={`${Translate[lang]?.password}`}
							onChange={(e) => inputHandler(e)}
						/>
					</div>
					<div className="col-6 mb-3">
						<label className="text-label">{Translate[lang]?.roles}</label>
						<Select
							value={formData?.role}
							name="role"
							placeholder={Translate[lang]?.select}
							options={rolesOptions}
							onChange={(e) => setFormData({ ...formData, role: e })}
						/>
					</div>
				</div>
				<div className="d-flex justify-content-between mt-4">
					<Button
						variant="secondary"
						type="button"
						onClick={() => navigate("/admins")}>
						{Translate[lang]?.cancel}
					</Button>
					<Button variant="primary" type="submit" disabled={loading}>
						{Translate[lang]?.submit}
					</Button>
				</div>
			</AvForm>
		</Card>
	);
};

export default AddAdmin;
