import React, { Fragment, useEffect } from "react";
import { useState } from "react";
import { Row, Col, Card, Table, Button } from "react-bootstrap";
import { useSelector } from "react-redux";
import Loader from "../../common/Loader";
import NoData from "../../common/NoData";
import Pagination from "../../common/Pagination/Pagination";
import { Translate } from "../../Enums/Tranlate";
import CardItem from "./CardItem";
import "./style.scss";
import BrokerService from "../../../services/BrokerService";
import AddBrokerModal from "./AddBrokerModal";

const Broker = () => {
	const [data, setData] = useState([]);
	const [addModal, setAddModal] = useState(false);
	const [item, setItem] = useState({});
	const [hasData, setHasData] = useState(null);
	const [shouldUpdate, setShouldUpdate] = useState(false);
	const [loading, setLoading] = useState(false);
	const lang = useSelector((state) => state.auth?.lang);
	const Auth = useSelector((state) => state.auth?.auth);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const brokerService = new BrokerService();

	useEffect(() => {
		setLoading(true);
		brokerService.getList().then((res) => {
			if (res?.status) {
				setData(res?.data?.data?.data);
				setHasData(!!res?.data?.data?.total ? 1 : 0);
			}
			setLoading(false);
		});
	}, [shouldUpdate]);

	return (
		<Fragment>
			<Card className="mb-4">
				<Card.Body className="p-3">
					<div className="d-flex justify-content-between align-items-center">
						<div className="input-group w-50">
							<div>
								<span
									style={{
										fontWeight: "600",
										textTransform: "capitalize",
										color: "#000",
									}}>
									{Translate[lang].broker_managment}
								</span>
							</div>
						</div>
						{isExist("create_broker") && (
							<Button
								variant="primary"
								className="me-2 h-75"
								onClick={() => {
									setItem({});
									setAddModal(true);
								}}>
								<i
									className={`la la-plus ${
										lang === "en" ? "mr-2" : "ml-2"
									}`}></i>
								{Translate[lang]?.add} {Translate[lang]?.broker}
							</Button>
						)}
					</div>
				</Card.Body>
			</Card>
			<Row>
				<Col lg={12}>
					<Card>
						<Card.Body className={`${hasData === 0 && "text-center"} `}>
							{loading && (
								<div style={{ height: "300px" }}>
									<Loader />
								</div>
							)}
							{hasData === 1 && !loading && (
								<Table responsive bordered hover>
									<thead>
										<tr className="text-center">
											<th>
												<strong>{Translate[lang]?.name}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.email}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.capacity}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.active_requests}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.types}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.status}</strong>
											</th>
											<th>
												<strong>{Translate[lang]?.actions}</strong>
											</th>
										</tr>
									</thead>

									<tbody className="table-body">
										{data?.map((item, index) => {
											return (
												<CardItem
													index={index}
													key={index}
													item={item}
													setItem={setItem}
													setAddModal={setAddModal}
													setShouldUpdate={setShouldUpdate}
												/>
											);
										})}
									</tbody>
								</Table>
							)}
							{hasData === 0 && <NoData />}
						</Card.Body>
					</Card>
				</Col>
			</Row>

			{addModal && (
				<AddBrokerModal
					item={item}
					addModal={addModal}
					setShouldUpdate={setShouldUpdate}
					setAddModal={() => setAddModal(false)}
				/>
			)}
		</Fragment>
	);
};

export default Broker;
