import { useState } from "react";
import { Card, Table } from "react-bootstrap";
import { useSelector } from "react-redux";
import UserService from "../../../services/UserService";
import Loader from "../../common/Loader";
import NoData from "../../common/NoData";
import Pagination from "../../common/Pagination/Pagination";
import { Translate } from "../../Enums/Tranlate";
import CardItem from "./CardItem";

const Users = () => {
	const [users, setUsers] = useState([]);
	const [hasData, setHasData] = useState(null);
	const [shouldUpdate, setShouldUpdate] = useState(false);
	const [loading, setLoading] = useState(false);
	const [params, setParams] = useState({});
	const lang = useSelector((state) => state?.auth.lang);
	const userService = new UserService();

	return (
		<>
			<Card>
				<Card.Body className={`${hasData === 0 && "text-center"} `}>
					<div className="tabs-div mb-3">
						<span
							className={!params?.userType ? "active" : ""}
							onClick={() => {
								setParams("");
								setShouldUpdate((prev) => !prev);
							}}>
							{Translate[lang].all}
						</span>
						<span
							className={params?.userType === "INDIVIDUAL" ? "active" : ""}
							onClick={() => {
								setParams({ userType: "INDIVIDUAL" });
								setShouldUpdate((prev) => !prev);
							}}>
							{Translate[lang].individual}
						</span>
						<span
							className={params?.userType === "COMPANY" ? "active" : ""}
							onClick={() => {
								setParams({ userType: "COMPANY" });
								setShouldUpdate((prev) => !prev);
							}}>
							{Translate[lang].company}
						</span>
					</div>
					{loading && (
						<div style={{ height: "300px" }}>
							<Loader />
						</div>
					)}
					{hasData === 1 && !loading && (
						<Table responsive bordered hover>
							<thead>
								<tr className="text-center">
									<th>
										<strong>{Translate[lang]?.name}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.email}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.phone}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.type}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.status}</strong>
									</th>
									<th>
										<strong>{Translate[lang]?.actions}</strong>
									</th>
								</tr>
							</thead>
							<tbody>
								{users?.map((item, index) => {
									return (
										<CardItem
											key={index}
											index={index}
											item={item}
											setShouldUpdate={setShouldUpdate}
										/>
									);
								})}
							</tbody>
						</Table>
					)}

					{hasData === 0 && <NoData />}

					<Pagination
						setData={setUsers}
						service={userService}
						shouldUpdate={shouldUpdate}
						setHasData={setHasData}
						setLoading={setLoading}
						search={""}
						param={params}
					/>
				</Card.Body>
			</Card>
		</>
	);
};
export default Users;
