import { useEffect, useState } from "react";
import { Button, Col, Modal, Row } from "react-bootstrap";
import { AvField, AvForm } from "availity-reactstrap-validation";
import { toast } from "react-toastify";
import Select from "react-select";
import { useSelector } from "react-redux";
import BrokerService from "../../../services/BrokerService";
import { Translate } from "../../Enums/Tranlate";
import ScrollPagination from "../ScrollPagination";
import ClearanceService from "../../../services/ClearanceService";
import TransportService from "../../../services/TransportService";

const AssignModal = ({ assign, setAssign, item, type, setShouldUpdate }) => {
	const lang = useSelector((state) => state.auth?.lang);
	const [broker, setBroker] = useState("");
	const [loading, setLoading] = useState(false);
	const brokerService = new BrokerService();
	const Service =
		type === "clearance" ? new ClearanceService() : new TransportService();

	useEffect(() => {
		if (!!item?.brokerId) {
			setBroker({
				label: item?.broker?.name,
				value: item?.broker?.id,
			});
		}
	}, [item]);

	const submit = () => {
		let data = {
			brokerId: !!broker ? broker?.value : null,
		};
		setLoading(true);
		Service.assignBroker(item?.id, data)?.then((res) => {
			if (res && res?.status === 200) {
				toast.success("Broker Status Updated Successfully");
				setAssign();
				setShouldUpdate((prev) => !prev);
			}
			setLoading(false);
		});
	};

	return (
		<Modal
			className={lang === "en" ? "en fade" : "ar fade"}
			style={{ textAlign: lang === "en" ? "left" : "right" }}
			show={assign}
			onHide={() => {
				setAssign();
			}}>
			<AvForm className="form-horizontal" onValidSubmit={submit}>
				<Modal.Header>
					<Modal.Title>
						{Translate[lang][!!item?.brokerId ? "reassign" : "assign"]}
					</Modal.Title>
					<Button
						variant=""
						className="close"
						style={{
							right: lang === "en" ? "0" : "auto",
							left: lang === "ar" ? "0" : "auto",
						}}
						onClick={() => {
							setAssign();
						}}>
						<span>&times;</span>
					</Button>
				</Modal.Header>
				<Modal.Body>
					<Row>
						<Col md={12} className="mb-3">
							<label className="text-label">{Translate[lang].broker}</label>
							<ScrollPagination
								Service={brokerService}
								value={broker}
								nameVal={"name"}
								setData={(e) => setBroker(e)}
							/>
						</Col>
					</Row>
				</Modal.Body>
				<Modal.Footer>
					<Button
						variant="primary"
						className="w-100"
						type="submit"
						disabled={loading}>
						{Translate[lang][!!item?.brokerId ? "reassign" : "assign"]}
					</Button>
				</Modal.Footer>
			</AvForm>
		</Modal>
	);
};

export default AssignModal;
