import { useState } from "react";
import { Badge } from "react-bootstrap";
import { useSelector } from "react-redux";
import DeleteModal from "../../../common/DeleteModal";
import { Translate } from "../../../Enums/Tranlate";
import BrokerService from "../../../../services/BrokerService";
import editIcon from "../../../../images/icons/edit.svg";
import trashIcon from "../../../../images/icons/delete.svg";
import { toast } from "react-toastify";

const CardItem = ({ item, setItem, index, setAddModal, setShouldUpdate }) => {
	const [deleteModal, setDeleteModal] = useState(false);
	const [status, setStatus] = useState(item?.status);
	const Auth = useSelector((state) => state.auth?.auth);
	const lang = useSelector((state) => state.auth?.lang);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const brokerService = new BrokerService();

	const changeStatus = () => {
		let data = {
			status: item?.status === "ACTIVE" ? "INACTIVE" : "ACTIVE",
		};
		brokerService.updateStatus(item?.id, data).then((res) => {
			if (res.status) {
				toast.success("Status Updated Successfuly");
				setStatus(item?.status === "ACTIVE" ? "INACTIVE" : "ACTIVE");
			}
		});
	};
	return (
		<tr key={index} className="text-center">
			<td>
				<strong>{item.name}</strong>
			</td>
			<td>{item.email}</td>
			<td>{item.capacity}</td>
			<td>{item.activeRequests}</td>
			<td className="d-flex gap-8">
				{item.types?.map((res) => {
					return (
						<Badge variant="outline-primary">
							{Translate[lang][res?.toLocaleLowerCase()]}
						</Badge>
					);
				})}
			</td>
			<td>
				<Badge
					className="cursor-pointer"
					variant={status === "ACTIVE" ? "primary" : "danger"}
					onClick={changeStatus}>
					{Translate[lang][status?.toLocaleLowerCase()]}
				</Badge>
			</td>
			<td>
				<div className="d-flex justify-content-center" style={{ gap: "20px" }}>
					{isExist("update_broker") && (
						<img
							src={editIcon}
							alt="view"
							width={24}
							onClick={() => {
								setItem(item);
								setAddModal(true);
							}}
						/>
					)}
					{isExist("delete_broker") && (
						<img
							src={trashIcon}
							className="cursor-pointer"
							onClick={() => setDeleteModal(true)}
							alt="trash"
							width={24}
						/>
					)}
				</div>
			</td>

			{deleteModal && (
				<DeleteModal
					open={deleteModal}
					titleMsg={item.name}
					deletedItem={item}
					modelService={brokerService}
					onCloseModal={setDeleteModal}
					setShouldUpdate={setShouldUpdate}
				/>
			)}
		</tr>
	);
};
export default CardItem;
