import React, { useEffect, useReducer, useState } from "react";
/// Scroll
import Collapse from "react-bootstrap/Collapse";
/// Link
import { Link, NavLink } from "react-router-dom";
import logoImg from "../../../images/logo.svg";
import { MenuList, BrokerMenuList } from "../../Enums/Menu";
import { useScrollPosition } from "@n8tb1t/use-scroll-position";
import { useDispatch, useSelector } from "react-redux";
import { Translate } from "../../Enums/Tranlate";

const reducer = (previousState, updatedState) => ({
	...previousState,
	...updatedState,
});

const initialState = {
	active: "",
	activeSubmenu: "",
};

const SideBar = ({ toggle, setToggle }) => {
	const [active, setActive] = useState("");
	const [state, setState] = useReducer(reducer, initialState);
	const lang = useSelector((state) => state.auth?.lang);
	const Auth = useSelector((state) => state.auth?.auth);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const [list, setList] = useState(
		Auth.type === "admin" ? MenuList : BrokerMenuList
	);

	//For scroll
	const [hideOnScroll, setHideOnScroll] = useState(true);
	useScrollPosition(
		({ prevPos, currPos }) => {
			const isShow = currPos.y > prevPos.y;
			if (isShow !== hideOnScroll) setHideOnScroll(isShow);
		},
		[hideOnScroll]
	);

	const handleMenuActive = (status) => {
		setState({ active: status });
		if (
			state.active === status &&
			list.filter((res) => res?.title === status)[0]?.hasOwnProperty("content")
		) {
			setState({ active: "" });
		}
	};

	useEffect(() => {
		let page = window.location.pathname;
		let filter = list?.filter((res) => `${res.to}` === page?.split("/")[1]);

		if (filter.length > 0) handleMenuActive(filter[0].title);
	}, [window.location.pathname]);

	/// Path
	let path = window.location.pathname;
	path = path.split("/");
	path = path[path.length - 1];

	return (
		<div className={`deznav ${toggle ? "show-menu" : ""}`}>
			<Link to="/" className="brand-logo">
				<img
					className="brand-title m-auto"
					src={logoImg}
					alt="logo"
					style={{
						borderRadius: "0",
					}}
				/>
			</Link>
			<div className="mobile-button">
				<div className="w-100 d-flex justify-content-between align-items-center">
					<Link to="/">
						<img
							className="m-auto"
							src={logoImg}
							alt="logo"
							style={{
								borderRadius: "0",
							}}
						/>
					</Link>
					<div
						onClick={() => setToggle(false)}
						style={{ fontSize: "24px" }}
						className={`${toggle ? "is-active" : ""}`}>
						<i className="la la-angle-double-right"></i>
					</div>
				</div>
			</div>
			<div className="deznav-scroll">
				<ul className="metismenu" id="menu">
					{list.map((data, index) => {
						let menuClass = data.classsChange;
						return (
							<li
								className={`${state.active === data.title ? "mm-active" : ""}`}
								key={index}>
								{data?.content && !!data.content.length ? (
									<>
										<Link
											to={"#"}
											className="has-arrow d-flex align-items-center justify-content-between"
											onClick={() => {
												handleMenuActive(data.title);
											}}>
											<div>
												{data.icon}
												<span className="nav-text">
													{Translate[lang][data.text]}
												</span>
											</div>
											<svg
												width="16"
												height="16"
												viewBox="0 0 14 14"
												fill="none"
												xmlns="http://www.w3.org/2000/svg">
												<path
													d="M11.0666 4.9722L7.44438 8.59442C7.0166 9.0222 6.3166 9.0222 5.88882 8.59442L2.2666 4.9722"
													stroke="#292D32"
													stroke-width="0.833333"
													stroke-miterlimit="10"
													stroke-linecap="round"
													stroke-linejoin="round"
												/>
											</svg>
										</Link>
										<Collapse in={state.active === data.title ? true : false}>
											<ul
												className={`${
													menuClass === "mm-collapse" ? "mm-show" : ""
												}`}>
												{data.content?.map((data, index) => {
													//.filter(res=> isExist(res.rule))
													return (
														<li
															key={index}
															className={`${
																state.activeSubmenu === data.title
																	? "mm-active"
																	: ""
															}`}>
															<NavLink
																to={data.to}
																onClick={() => {
																	setToggle(false);
																	setActive(data.text);
																}}
																className={`${
																	active === data.text ? "active-link" : ""
																}`}>
																{Translate[lang][data.text]}
															</NavLink>
														</li>
													);
												})}
											</ul>
										</Collapse>
									</>
								) : (
									<Link
										to={data.to}
										className="d-flex"
										onClick={() => {
											handleMenuActive(data.title);
											setToggle(false);
										}}>
										{data.icon}
										<span className="nav-text">
											{Translate[lang][data.text]}
										</span>
									</Link>
								)}
							</li>
						);
					})}
				</ul>
			</div>
		</div>
	);
};

export default SideBar;
