import { useEffect, useState } from "react";
import { Button, Col, Modal, Row } from "react-bootstrap";
import { AvField, AvForm } from "availity-reactstrap-validation";
import { toast } from "react-toastify";
import Select from "react-select";
import { useSelector } from "react-redux";
import { Translate } from "../../../Enums/Tranlate";
import BrokerService from "../../../../services/BrokerBrokerService";

const StatusModal = ({
	statusModal,
	setStatusModal,
	item,
	type,
	setShouldUpdate,
}) => {
	const lang = useSelector((state) => state.auth?.lang);
	const typesOptions = [
		{ label: Translate[lang].pending, value: "pending" },
		{ label: Translate[lang].in_progress, value: "in_progress" },
		{ label: Translate[lang].completed, value: "completed" },
		{ label: Translate[lang].rejected, value: "rejected" },
	];
	const [status, setStatus] = useState({});
	const [loading, setLoading] = useState(false);
	const brokerService = new BrokerService();

	useEffect(() => {
		setStatus({
			label: Translate[lang][item?.status],
			value: item?.status,
		});
	}, [item]);

	const submit = () => {
		let data = {
			status: status?.value,
		};
		setLoading(true);
		brokerService.updateStatus(item?.id, type, data)?.then((res) => {
			if (res && res?.status === 200) {
				toast.success("Broker Status Updated Successfully");
				setStatusModal();
				setShouldUpdate((prev) => !prev);
			}
			setLoading(false);
		});
	};

	return (
		<Modal
			className={lang === "en" ? "en fade" : "ar fade"}
			style={{ textAlign: lang === "en" ? "left" : "right" }}
			show={statusModal}
			onHide={() => {
				setStatusModal();
			}}>
			<AvForm className="form-horizontal" onValidSubmit={submit}>
				<Modal.Header>
					<Modal.Title>
						{Translate[lang]?.edit} {Translate[lang]?.status}
					</Modal.Title>
					<Button
						variant=""
						className="close"
						style={{
							right: lang === "en" ? "0" : "auto",
							left: lang === "ar" ? "0" : "auto",
						}}
						onClick={() => {
							setStatusModal();
						}}>
						<span>&times;</span>
					</Button>
				</Modal.Header>
				<Modal.Body>
					<Row>
						<Col md={12} className="mb-3">
							<label className="text-label">{Translate[lang].status}</label>
							<Select
								value={status}
								name="types"
								placeholder={Translate[lang].select}
								options={typesOptions}
								onChange={(e) => setStatus(e)}
							/>
						</Col>
					</Row>
				</Modal.Body>
				<Modal.Footer>
					<Button onClick={setStatusModal} variant="danger light">
						{Translate[lang]?.close}
					</Button>
					<Button variant="primary" type="submit" disabled={loading}>
						{Translate[lang]?.edit}
					</Button>
				</Modal.Footer>
			</AvForm>
		</Modal>
	);
};

export default StatusModal;
