import { useEffect, useState } from "react";
import { Button, Card, Table } from "react-bootstrap";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import AdminService from "../../../services/AdminService";
import Loader from "../../common/Loader";
import NoData from "../../common/NoData";
import { Translate } from "../../Enums/Tranlate";
import CardItem from "./CardItem";
import "./style.scss";

const Admins = () => {
	const [admins, setAdmins] = useState(null);
	const [hasData, setHasData] = useState(null);
	const [search, setSearch] = useState(null);
	const [shouldUpdate, setShouldUpdate] = useState(false);
	const [loading, setLoading] = useState(false);
	const navigate = useNavigate();
	const adminService = new AdminService();
	const Auth = useSelector((state) => state.auth?.auth);
	const isExist = (data) => Auth?.permissions?.includes(data);
	const lang = useSelector((state) => state.auth?.lang);

	useEffect(() => {
		setLoading(true);
		adminService.getList().then((res) => {
			if (res?.status) {
				setAdmins(res?.data?.data);
				setHasData(!!res?.data?.data?.length ? 1 : 0);
			}
			setLoading(false);
		});
	}, [shouldUpdate]);

	return (
		<div className="admin">
			<Card className="mb-3">
				<Card.Body className="d-flex justify-content-between p-3 align-items-center">
					<div>
						<span
							style={{
								fontWeight: "600",
								textTransform: "capitalize",
								color: "#000",
							}}>
							{Translate[lang].admins}
						</span>
					</div>
					<div>
						{isExist("admin") ||
							(true && (
								<Button
									variant="primary"
									style={{ fontWeight: "400" }}
									className="me-2 h-75 radius-5"
									onClick={() => navigate("/admins/add-admins")}>
									<i
										className={`la la-plus ${
											lang === "en" ? "mr-2" : "ml-2"
										}`}></i>
									{Translate[lang]?.add_admin}
								</Button>
							))}
					</div>
				</Card.Body>
			</Card>

			<Card>
				<Card.Body className={`${hasData === 0 ? "text-center" : ""}`}>
					{loading && (
						<div style={{ height: "300px" }}>
							<Loader />
						</div>
					)}
					{hasData === 1 && !loading && (
						<Table responsive bordered hover>
							<thead>
								<tr>
									<th className="px-2">
										<strong>{Translate[lang]?.email}</strong>
									</th>
									<th className="px-2">
										<strong>{Translate[lang]?.permissions}</strong>
									</th>
									<th className="px-2 text-center">
										<strong>{Translate[lang]?.actions}</strong>
									</th>
								</tr>
							</thead>
							<tbody>
								{admins?.length > 0 &&
									admins?.map((item, index) => {
										return (
											<CardItem
												key={index}
												index={index}
												item={item}
												setShouldUpdate={setShouldUpdate}
											/>
										);
									})}
							</tbody>
						</Table>
					)}
					{hasData === 0 && <NoData />}
				</Card.Body>
			</Card>
		</div>
	);
};
export default Admins;
